88		case <-done:
89		case <-time.After(5 * time.Second):
90			t.Fatal("并发 Close 互相等待，未能全部结束")
91		}
92		close(errCh)
93		for e := range errCh {
94			t.Errorf("concurrent close: %v", e)
95		}
96		if len(returned) != n {
97			t.Fatalf("应有 %d 次 Close 成功返回，got %d", n, len(returned))
98		}
99	
100		// 任意一次 Close 返回后都可安全重开：运行作业为中断失败、原因可查、
101		// 无成功归档与实际计算输入；排队作业原样保留并继续按序处理。
102		s2, err := Open(dir)
103		if err != nil {
104			t.Fatalf("reopen: %v", err)
105		}
106		defer func() { _ = s2.Close() }()
107	
108		g1, err := s2.Get(j1.ID)
109		if err != nil {
110			t.Fatalf("get j1: %v", err)
111		}
112		if g1.Status != StatusFailed || !strings.Contains(g1.FailureReason, "计算被中断") {
113			t.Fatalf("j1 status=%s reason=%q，want 计算被中断失败", g1.Status, g1.FailureReason)
114		}
115		if g1.Archive != nil || len(g1.EffectiveValues) != 0 {
116			t.Fatalf("中断失败不应留下成功归档或实际输入，got archive=%v effective=%v",
117				g1.Archive, g1.EffectiveValues)
118		}
119	
120		g2 := waitStatus(t, s2, j2.ID, StatusSucceeded)
121		if g2.Archive == nil || g2.Archive.Sum != 30 {
122			t.Fatalf("排队作业重开后应正常成功（总和 30），got status=%s", g2.Status)
123		}
124	}
125	
126	// TestConcurrentCloseIdleStore 没有运行中作业的空闲归档被并发关闭：每次调用
127	// 都正常返回、互不卡死；完全关闭后的再次 Close 立即成功。
128	func TestConcurrentCloseIdleStore(t *testing.T) {
129		s, _ := openTestStore(t)
130	
131		const n = 8
132		var wg sync.WaitGroup
133		for i := 0; i < n; i++ {
134			wg.Add(1)
135			go func() {
136				defer wg.Done()
137				if err := s.Close(); err != nil {
138					t.Errorf("idle close: %v", err)
139				}
140			}()
141		}
142		wg.Wait()
143	
144		if err := s.Close(); err != nil {
145			t.Fatalf("close after fully closed: %v", err)
146		}
147		if _, err := s.Submit(SubmitRequest{Submitter: "a", Values: []int64{1}}); !errors.Is(err, ErrStoreClosed) {
148			t.Fatalf("submit after close: %v", err)
149		}
150	}
